function impact(s,topic,mode,returnVisit){let contacts=0;for(let i=0;i<s.voters.length;i++){if(rand(s.seed,'contact',topic,returnVisit?1:0,i)>.045)continue;contacts++;const v=s.voters[i];let delta=0;if(['window','maintenance','evidence'].includes(mode))delta=.009*(v.priority-.45);else if(['alternate','survey'].includes(mode))delta=.009*(.55-v.priority);else if(mode==='honest'||mode==='retract')delta=.003*(v.accuracy-.5);else if(mode==='insist')delta=.012*(.28-v.accuracy);v.support[0]=Math.max(.002,Math.min(.08,v.support[0]+delta));}s.player.recognition=Math.min(35,s.player.recognition+Math.max(1,Math.round(contacts/POPULATION*100)*(returnVisit?.4:1)));}
function complete(s,mode,body,lines=[]){const topic=s.pending.topic,t=TOPICS[topic];impact(s,topic,mode,s.pending.returnVisit);const initial=s.pending.initial;s.reaction={title:`${t.npc.name}的回應`,npc:t.npc.name,body,lines,quote:initial?.text||null,facts:[]};if(s.rival.news?.kind==='criticism'&&s.rival.news.topic===topic){s.reaction.lines.push(`周沐引用了你的原話：「${s.rival.news.quote}」`);const corrected=s.promises.filter(p=>p.topic===topic&&p.type==='guarantee').every(p=>p.status==='corrected');s.rival.news.response=corrected?'你已公開更正，原話與更正並列留存。':'目前沒有補上依據，原保證仍待說明。';s.reaction.lines.push(corrected?'你的更正也同時進入公開紀錄，對手不能把未更正當成現在的立場。':s.rival.news.response);const prior=s.rival.history.findLast(n=>n.kind==='criticism'&&n.topic===topic);if(prior)prior.response=s.rival.news.response;}s.journal.push({kind:'visit',topic,title:`拜訪${t.npc.name}${s.pending.returnVisit?'・回訪':''}`,text:body,quote:initial?.text||null,lines:clone(s.reaction.lines),cost:2000,time:1});s.pending=null;s.phase='reaction';return s.reaction;}
