 s.pending.initial={id,text:option.text};const plan=t.plans.find(p=>p.id===id);if(plan){s.positions[topic]=id;settlePromises(s,topic,'reply');return complete(s,id,plan.reaction,[`你引用了已讀資料：${t.facts[1].title}、${t.facts[2].title}。`,'這個方案有人認同，也有人在意它的代價；不保證支持。']);}
